SELECT x.n, x.body,
  json_patch(json_patch('{}', json_object('event', x.event, 'agent_type', x.agent_type, 'subagent_type', x.asked_type, 'description', x.description, 'effort', x.effort, 'first_line', x.first_line, 'model', x.model, 'model_id', x.model_id, 'prompt_sha', x.prompt_sha, 'session_id', x.session, 'tool_use_id', x.tool_use_id, 'declared', x.declared, 'route', x.route, 'agent_type_escape', x.agent_type_escape, 'status', x.status, 'report', x.report, 'profile', x.profile, 'profile_why', x.profile_why, 'lane', x.lane, 'meter', CASE WHEN coalesce(x.meter_read_at, x.meter_5h, x.meter_7d, x.meter_age_h, x.meter_ok) IS NOT NULL THEN json_object('read_at', x.meter_read_at, '5h', x.meter_5h, '7d', x.meter_7d, 'age_h', x.meter_age_h, 'ok', CASE x.meter_ok WHEN 1 THEN json('true') WHEN 0 THEN json('false') END) END, 'no_item_why', x.no_item_why, 'pool', CASE WHEN coalesce(x.pool_said, x.pool_why) IS NOT NULL THEN json_object('said', x.pool_said, 'why', x.pool_why) END, 'tokens', CASE WHEN coalesce(x.tokens_cache_creation, x.tokens_cache_read, x.tokens_input, x.tokens_output, x.tokens_total) IS NOT NULL THEN json_object('cache_creation', x.tokens_cache_creation, 'cache_read', x.tokens_cache_read, 'input', x.tokens_input, 'output', x.tokens_output, 'total', x.tokens_total) END, 'cores', x.cores, 'exempt', CASE x.exempt WHEN 1 THEN json('true') WHEN 0 THEN json('false') END, 'explored', CASE x.explored WHEN 1 THEN json('true') WHEN 0 THEN json('false') END, 'tokens_settled', CASE x.tokens_settled WHEN 1 THEN json('true') WHEN 0 THEN json('false') END, 'load', CASE WHEN x.load1 IS NOT NULL THEN json_array(x.load1, x.load5, x.load15) END, 'tags', json(nullif(nullif((SELECT json_group_array(c.value ORDER BY c.ord) FROM spawn_lists c WHERE c.n = x.n AND c.kind = 'tag'), '[]'), '{}')), 'items', json(nullif(nullif((SELECT json_group_array(c.value ORDER BY c.ord) FROM spawn_lists c WHERE c.n = x.n AND c.kind = 'item'), '[]'), '{}')), 'faults', json(nullif(nullif((SELECT json_group_array(c.value ORDER BY c.ord) FROM spawn_lists c WHERE c.n = x.n AND c.kind = 'fault'), '[]'), '{}')), 'scratch_loose', json(nullif(nullif((SELECT json_group_array(c.value ORDER BY c.ord) FROM spawn_lists c WHERE c.n = x.n AND c.kind = 'scratch_loose'), '[]'), '{}')), 'ci_direct', json(nullif(nullif((SELECT json_group_array(c.value ORDER BY c.ord) FROM spawn_lists c WHERE c.n = x.n AND c.kind = 'ci_direct'), '[]'), '{}')), 'apps', coalesce(json(nullif(nullif((SELECT json_group_array(c.value ORDER BY c.ord) FROM spawn_lists c WHERE c.n = x.n AND c.kind = 'app'), '[]'), '{}')), CASE WHEN coalesce((SELECT 1 FROM spawn_lists c WHERE c.n = x.n AND c.kind = 'app_before' LIMIT 1), (SELECT 1 FROM spawn_lists c WHERE c.n = x.n AND c.kind = 'app_failed' LIMIT 1), (SELECT 1 FROM spawn_lists c WHERE c.n = x.n AND c.kind = 'app_missing' LIMIT 1), (SELECT 1 FROM spawn_lists c WHERE c.n = x.n AND c.kind = 'app_relaunched' LIMIT 1), (SELECT 1 FROM spawn_app_exits c WHERE c.n = x.n LIMIT 1)) IS NOT NULL THEN json_object('before', json(nullif(nullif((SELECT json_group_array(c.value ORDER BY c.ord) FROM spawn_lists c WHERE c.n = x.n AND c.kind = 'app_before'), '[]'), '{}')), 'failed', json(nullif(nullif((SELECT json_group_array(c.value ORDER BY c.ord) FROM spawn_lists c WHERE c.n = x.n AND c.kind = 'app_failed'), '[]'), '{}')), 'missing', json(nullif(nullif((SELECT json_group_array(c.value ORDER BY c.ord) FROM spawn_lists c WHERE c.n = x.n AND c.kind = 'app_missing'), '[]'), '{}')), 'relaunched', json(nullif(nullif((SELECT json_group_array(c.value ORDER BY c.ord) FROM spawn_lists c WHERE c.n = x.n AND c.kind = 'app_relaunched'), '[]'), '{}')), 'exits', json(nullif(nullif((SELECT json_group_object(c.app, json_patch('{}', json_object('gone_by', c.gone_by, 'last_seen', c.last_seen))) FROM spawn_app_exits c WHERE c.n = x.n), '[]'), '{}'))) END), 'agent_id', x.agent, 'time', strftime('%Y-%m-%dT%H:%M:%S+00:00', x.at, 'unixepoch'))), coalesce(x.rest, '{}')) AS doc
FROM agent_spawns x
